import{_ as l,c as e,aU as s,a as n}from"./chunks/framework.DIXiA2XH.js";const y=JSON.parse('{"title":"房子相关","description":"","frontmatter":{},"headers":[],"relativePath":"note/knowledge/05-房子相关.md","filePath":"note/knowledge/05-房子相关.md","lastUpdated":1786542501000}'),r={name:"note/knowledge/05-房子相关.md"};function g(o,t,a,i,d,x){return n(),e("div",null,[...t[0]||(t[0]=[s(`<h1 id="房子相关" tabindex="-1">房子相关 <a class="header-anchor" href="#房子相关" aria-label="Permalink to &quot;房子相关&quot;">​</a></h1><h2 id="等额本息和等额本金" tabindex="-1">等额本息和等额本金 <a class="header-anchor" href="#等额本息和等额本金" aria-label="Permalink to &quot;等额本息和等额本金&quot;">​</a></h2><p>举个例子，年利率6%，月利率等于0.5%。贷款12万，12期还清。利息多少呢？12万*6%=7200元 。 这种算法是错误的，实际还的钱要远远低于7200元。</p><h3 id="等额本金" tabindex="-1">等额本金 <a class="header-anchor" href="#等额本金" aria-label="Permalink to &quot;等额本金&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;"></th><th style="text-align:left;">本金</th><th style="text-align:left;">利息</th><th style="text-align:left;">每月需还</th></tr></thead><tbody><tr><td style="text-align:left;">第一个月</td><td style="text-align:left;">1万</td><td style="text-align:left;">12w*0.5%=600</td><td style="text-align:left;">10600</td></tr><tr><td style="text-align:left;">第二个月</td><td style="text-align:left;">1万</td><td style="text-align:left;">11w*0.5%=550</td><td style="text-align:left;">10550</td></tr><tr><td style="text-align:left;">第三个月</td><td style="text-align:left;">1万</td><td style="text-align:left;">10w*0.5%=500</td><td style="text-align:left;">10500</td></tr><tr><td style="text-align:left;">...</td><td style="text-align:left;"></td><td style="text-align:left;"></td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;">第12个月</td><td style="text-align:left;">1万</td><td style="text-align:left;">1w*0.5%=50</td><td style="text-align:left;">10050</td></tr></tbody></table><p>每月的利息这是一个等差数列。 600+550+500+...+50 = (650/2)*12 = 3900元</p><h3 id="等额本息" tabindex="-1">等额本息 <a class="header-anchor" href="#等额本息" aria-label="Permalink to &quot;等额本息&quot;">​</a></h3><blockquote><p>计算器： <a href="https://www.hicalc.com/program/162" target="_blank" rel="noreferrer">https://www.hicalc.com/program/162</a></p></blockquote><p>这个的特点是每月固定还xx元。这个算法有点稍微的麻烦。</p><p>举个例子，A1,A2,A3....A12 代表每个月剩余的还款金额。 假设每月还款 X元 (本金+利息)</p><ul><li>A0 = 12万 （一开始欠12w）</li><li>(第一个月)A1 = A0*(1+0.5%) - X元</li><li>(第二个月)A2 = A1*(1+0.5%) - X元</li><li>...</li><li>(第12个月)A12 = A11*(1+0.5%) - X元 = 0元</li></ul><p>求A的值。。。 A=10328元。</p><div class="language-vue vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">每月还款额(元):</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">10327.97</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">总的还款额(元):</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">123935.66</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">总的利息额(元):</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">3935.66</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><h2 id="各种房子指标" tabindex="-1">各种房子指标 <a class="header-anchor" href="#各种房子指标" aria-label="Permalink to &quot;各种房子指标&quot;">​</a></h2><h3 id="容积率" tabindex="-1">容积率 <a class="header-anchor" href="#容积率" aria-label="Permalink to &quot;容积率&quot;">​</a></h3><p>容积率 = 土地面积上的建筑面积总和/土地面积。</p><p>打个比方：你家小区占地1w平房，建筑面积2w平方，那么你们小区的容积率就是2。再打个生动的比喻，就好比一个装鸡的笼子，装一个鸡容积率就是1，装2个就是2。</p><p>所以容积率越小越好，越舒适。</p><table tabindex="0"><thead><tr><th style="text-align:left;">容积率</th><th style="text-align:left;">类型</th></tr></thead><tbody><tr><td style="text-align:left;">0.2-0.5</td><td style="text-align:left;">独栋别墅</td></tr><tr><td style="text-align:left;">0.4-0.7</td><td style="text-align:left;">联排别墅</td></tr><tr><td style="text-align:left;">0.8-1.2</td><td style="text-align:left;">6层以下小洋房</td></tr><tr><td style="text-align:left;">1.5-2</td><td style="text-align:left;">11层以下的小高层</td></tr><tr><td style="text-align:left;">1.8-2.5</td><td style="text-align:left;">18层以下的高层住宅</td></tr><tr><td style="text-align:left;">2.4-4.5</td><td style="text-align:left;">18层以上的高层住宅</td></tr></tbody></table><h2 id="二手房买卖" tabindex="-1">二手房买卖 <a class="header-anchor" href="#二手房买卖" aria-label="Permalink to &quot;二手房买卖&quot;">​</a></h2><p><strong>先设定一个“小明卖房”的场景</strong></p><ul><li><strong>房子面积</strong>：98平米</li><li><strong>成交价</strong>：100万元（为了方便计算）</li><li><strong>小明当年买入价</strong>：80万元（原值）</li><li><strong>目前房子状态</strong>：小明<strong>只有这一套房</strong>，而且契税已经交了<strong>3年多</strong>（即“满三”）</li></ul><p>第一步：小明卖这套房，要交多少“主要的税”？</p><p>二手房买卖，主要涉及三大税：<strong>增值税、个人所得税、契税</strong>。</p><table tabindex="0"><thead><tr><th style="text-align:left;">税种</th><th style="text-align:left;">法律规定该谁交？</th><th style="text-align:left;">在你的例子里，要交多少？</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>增值税</strong></td><td style="text-align:left;">卖家（小明）</td><td style="text-align:left;"><strong>0元</strong>。因为“满二”免征。</td></tr><tr><td style="text-align:left;"><strong>个人所得税</strong></td><td style="text-align:left;">卖家（小明）</td><td style="text-align:left;"><strong>可能要交</strong>。因为只“满三”，不满足“满五唯一”，所以不能免。</td></tr><tr><td style="text-align:left;"><strong>契税</strong></td><td style="text-align:left;">买家（你）</td><td style="text-align:left;"><strong>1万元</strong>（100万 × 1%）。这笔是买家必须交的。</td></tr></tbody></table><h3 id="_1-增值税-卖家出" tabindex="-1">1. 增值税 -- 卖家出 <a class="header-anchor" href="#_1-增值税-卖家出" aria-label="Permalink to &quot;1. 增值税 -- 卖家出&quot;">​</a></h3><div class="tip custom-block github-alert"><p class="custom-block-title">听名字就可以知道，房子增值的税咯，主要是为了调节房地产市场，而不是为了收钱。</p><p></p><p><strong>抑制短期投机（“房住不炒”）</strong>： - <strong>增值税“满二免征”</strong>：持有不足2年就卖，要交一笔很高的增值税（约5.3%）。这增加了短期炒房的成本，打击了快进快出的投机行为。持有超过2年再卖，说明是长期持有，就免税，这是鼓励长期自住。</p></div><p>“满二”免征！！！</p><p><strong>国家规定</strong>：个人将购买<strong>不足2年</strong>的住房对外销售的，全额征收增值税（税率约5.3%）。<strong>满2年（含）以上</strong>的普通住房，免征。</p><ul><li><strong>怎么算“满二”</strong>：看房产证登记日期或契税完税日期，<strong>哪个早算哪个</strong>。</li><li><strong>带入例子</strong>： <ul><li>小明的契税交了3年多了，肯定<strong>超过2年</strong>。</li><li>所以这笔约 <strong>5.3万元（100万×5.3%）</strong> 的增值税，<strong>一分钱都不用交</strong>。</li></ul></li><li><strong>对你的意义</strong>：这个税虽然是卖家法定要交的，但很多城市卖家会把这笔钱加进房价。现在免了，等于帮双方省了一大笔。</li></ul><h3 id="_2-个人所得税-卖家出" tabindex="-1">2. 个人所得税 -- 卖家出 <a class="header-anchor" href="#_2-个人所得税-卖家出" aria-label="Permalink to &quot;2. 个人所得税 -- 卖家出&quot;">​</a></h3><div class="tip custom-block github-alert"><p class="custom-block-title">个人所得税肯定是你挣钱了，也要交税，就和你上班发工资要交税一样。</p><p><strong>鼓励长期自住，支持刚需</strong>：</p><ul><li><strong>个税“满五唯一”免征</strong>：一个家庭只有一套房，并且住了5年以上才卖，说明这是真自住，不是炒房，国家就免收你的卖房所得税，减轻换房负担。</li><li><strong>契税按套数和面积差别化征收</strong>：首套小面积（≤140㎡）税率最低（1%），这是<strong>实实在在支持刚需购房者</strong>。二套房税率稍高，三套及以上更高，这是对多套房持有者的调节。</li></ul></div><div class="tip custom-block github-alert"><p class="custom-block-title">如果亏本卖房，个人所得税为 0 元，不用交</p><p></p><p>个人所得税 = （本次成交价 - 房屋原值 - 合理费用）× 20%</p><p>如果结果为正数：说明卖房赚了钱，就按盈利的20%交税。</p><p>如果结果为零或负数：说明卖房亏了钱或者平进平出，没有盈利，就不产生个人所得税，应交税额为 0 元。</p><p>但是，实操中需要注意一个风险：</p><p>在现实中，税务部门对“房屋原值”和“成交价”的认定，不一定完全按你的合同价来。如果税务部门认为你的成交价明显低于市场价（比如为了避税故意做低），他们会启动“核价”程序，按他们评估的市场价来计算税费。这就可能出现：你合同签80万，但税务评估这套房值100万，最后个税按（100万-100万）=0来算，或者按盈利来算。所以，合同价不能做得太低，要合理。</p></div><ul><li><strong>国家规定</strong>：个人转让自用<strong>5年以上</strong>，并且是<strong>家庭唯一</strong>生活用房取得的所得，<strong>免征</strong>个人所得税。</li><li><strong>怎么算“满五”</strong>：和“满二”一样，看契税或房产证日期，哪个早算哪个。</li><li><strong>怎么算“唯一”</strong>：指业主（及配偶）在<strong>该省份内</strong>仅拥有这一套住宅。</li><li><strong>带入例子</strong>： <ul><li>小明的契税只交了<strong>3年</strong>，不满5年，所以<strong>不满足“满五”</strong>。</li><li>因此，小明<strong>不能免征</strong>个人所得税。</li><li>这笔个税怎么算？通常是 <strong>（成交价 - 原价 - 合理费用）× 20%</strong>。粗略算一下：（100万 - 80万）×20% = <strong>4万元</strong>。</li></ul></li><li><strong>如果“满五唯一”呢？</strong> 假如小明这套房已经持有了6年，且是唯一住房，那这<strong>4万元的个税就全免了</strong>。</li></ul><h3 id="_3-契税如何算-买家出" tabindex="-1">3. 契税如何算 - 买家出 <a class="header-anchor" href="#_3-契税如何算-买家出" aria-label="Permalink to &quot;3. 契税如何算 - 买家出&quot;">​</a></h3><p>完整的契税税率表（按面积和套数）</p><table tabindex="0"><thead><tr><th style="text-align:left;">购房人住房情况</th><th style="text-align:left;">房屋面积</th><th style="text-align:left;">契税税率</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>首套房</strong></td><td style="text-align:left;">≤ 140㎡</td><td style="text-align:left;"><strong>1%</strong></td></tr><tr><td style="text-align:left;"><strong>首套房</strong></td><td style="text-align:left;">&gt; 140㎡</td><td style="text-align:left;"><strong>1.5%</strong></td></tr><tr><td style="text-align:left;"><strong>二套房</strong></td><td style="text-align:left;">≤ 140㎡</td><td style="text-align:left;"><strong>1%</strong></td></tr><tr><td style="text-align:left;"><strong>二套房</strong></td><td style="text-align:left;">&gt; 140㎡</td><td style="text-align:left;"><strong>2%</strong></td></tr><tr><td style="text-align:left;"><strong>三套及以上</strong></td><td style="text-align:left;">不限面积</td><td style="text-align:left;"><strong>3%</strong></td></tr></tbody></table><blockquote><p><strong>注意</strong>：北京、上海、广州、深圳四个一线城市，二套房契税统一为3%，不享受上述优惠。你问的平原新区（河南）按全国通用标准执行。</p></blockquote><h3 id="其他的还有什么钱" tabindex="-1">其他的还有什么钱 <a class="header-anchor" href="#其他的还有什么钱" aria-label="Permalink to &quot;其他的还有什么钱&quot;">​</a></h3><p>必须交的固定费用（金额不大）</p><table tabindex="0"><thead><tr><th style="text-align:left;">费用项目</th><th style="text-align:left;">谁收？</th><th style="text-align:left;">大概金额</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>不动产登记费</strong></td><td style="text-align:left;">不动产登记中心</td><td style="text-align:left;"><strong>80元 / 件</strong></td><td style="text-align:left;">办新房产证的工本费，住宅统一价。</td></tr><tr><td style="text-align:left;"><strong>贷款相关费用</strong>（如果你贷款）</td><td style="text-align:left;">银行/评估公司</td><td style="text-align:left;">约<strong>几千元</strong></td><td style="text-align:left;">包括银行可能收的抵押登记费（约80元），以及房屋评估费（约几百到一两千，看总价）。</td></tr><tr><td style="text-align:left;"><strong>印花税</strong></td><td style="text-align:left;">税务部门</td><td style="text-align:left;"><strong>5元</strong></td><td style="text-align:left;">贴在房产证上的印花，目前住宅免征，几乎可以忽略。</td></tr></tbody></table><p>看情况产生的费用（中介费是大头）</p><table tabindex="0"><thead><tr><th style="text-align:left;">费用项目</th><th style="text-align:left;">谁收？</th><th style="text-align:left;">大概金额</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>中介服务费</strong></td><td style="text-align:left;">房产中介</td><td style="text-align:left;"><strong>成交价的 1% ~ 3%</strong></td><td style="text-align:left;">这是一笔不小的开支。通常由买方出，但也可以谈。比如200万的房子，中介费可能在2万到6万之间。</td></tr><tr><td style="text-align:left;"><strong>物业、水电气等欠费</strong></td><td style="text-align:left;">物业公司</td><td style="text-align:left;">视情况而定</td><td style="text-align:left;">过户前，务必让业主结清所有欠费，并在合同里写明，否则你可能要替他补缴。</td></tr><tr><td style="text-align:left;"><strong>维修基金（公共维修金）</strong></td><td style="text-align:left;">业主</td><td style="text-align:left;"><strong>通常不用再交</strong></td><td style="text-align:left;">这笔钱在新房交付时就交过了。二手房交易中，这笔钱随房走，通常不需要买方再交。</td></tr></tbody></table><blockquote><p><strong>重点提示</strong>：<strong>中介费</strong>是你需要重点关注的费用。这笔钱是可以和中介<strong>砍价</strong>的，比如争取从2%谈到1.5%或更低。</p></blockquote><h3 id="契税时间和房产证日期" tabindex="-1">契税时间和房产证日期 <a class="header-anchor" href="#契税时间和房产证日期" aria-label="Permalink to &quot;契税时间和房产证日期&quot;">​</a></h3><p>✅ 关于“契税日期”的理解：</p><ul><li>你去税务局交契税，拿到完税证明，上面的“填发日期”就是<strong>契税日期</strong></li><li><strong>买新房</strong>：你也需要交契税。通常是你收房后，自己去税务局交，或者开发商代收代缴。你交完钱拿到税票，上面的日期同样就是<strong>契税日期</strong>。</li></ul><blockquote><p><strong>一句话总结</strong>：<strong>不管新房还是二手房，只要交契税，拿到的税票日期就是“契税日期”。</strong></p></blockquote><p>✅ 关于“房产证日期”的理解</p><ul><li><strong>买二手房</strong>：你办理过户，不动产登记中心审核通过，给你打印新房产证（不动产权证书），证上“登记日期”一栏，就是<strong>房产证日期</strong>。</li><li><strong>买新房</strong>：你收房后，开发商办好大产证，你去申请办自己名下的房产证，登记中心审核通过后打印出证，证上的“登记日期”就是<strong>房产证日期</strong>。</li></ul><blockquote><p><strong>一句话总结</strong>：<strong>不管新房还是二手房，你名下房产证上那个最终的“登记日期”，就是“房产证日期”。</strong></p></blockquote><h2 id="买新房需要交什么钱" tabindex="-1">买新房需要交什么钱 <a class="header-anchor" href="#买新房需要交什么钱" aria-label="Permalink to &quot;买新房需要交什么钱&quot;">​</a></h2><div class="tip custom-block github-alert"><p class="custom-block-title">总结</p><p>作为卖方，你挣钱了，必须交增值税和个人所得税。</p><p>作为买方，你啥都不用交。</p><p>但是你需要交契税，契税是什么呢？ 就是你向国家“买”那个房产证（不动产权证书）的使用权所交的“产权认证费”。</p><ul><li>在中国，土地和房屋的所有权（或使用权）发生转移时，国家需要以法律形式确认新的产权人。契税就是国家为你确认并保护这份新产权而收取的费用。</li><li>你交了契税，国家就在系统里登记了你的名字，你的房产证才有了法律效力，别人无法再主张这套房的权利。</li><li>不交契税，不动产权登记中心就不会给你办证，在法律上这套房还不算你的。</li><li>它和你买东西交的“增值税”不同。增值税是对“买卖行为”本身征税，而契税是对“产权归属变更”这件事征税。所以，只要房屋产权发生转移（买卖、赠与、交换），承受产权的一方就必须交契税。</li></ul></div><p>买新房（从开发商手里买的一手房），你作为买方，<strong>只需要缴纳契税</strong>。</p><ul><li><strong>增值税</strong>：<strong>不用交</strong>。开发商的房价里已经包含了增值税，这是开发商作为企业要交的税，不需要你额外再掏钱去税务部门缴纳。</li><li><strong>个人所得税</strong>：<strong>不用交</strong>。你是买房子花钱的一方，没有产生个人所得（盈利），所以当然没有个人所得税。只有卖房子赚钱的人才涉及这个税。</li><li><strong>契税</strong>：<strong>必须交</strong>。这是办理新房房产证的前提，税率和买二手房时一样，也是根据你的房屋套数和面积来算。</li></ul><table tabindex="0"><thead><tr><th style="text-align:left;">税费项目</th><th style="text-align:left;">法律规定该谁交</th><th style="text-align:left;">买新房（一手房）</th><th style="text-align:left;">买二手房</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>契税</strong></td><td style="text-align:left;">买方（你）</td><td style="text-align:left;"><strong>✅ 必须交</strong></td><td style="text-align:left;"><strong>✅ 必须交</strong></td></tr><tr><td style="text-align:left;"><strong>增值税</strong></td><td style="text-align:left;">卖方（开发商/原房东）</td><td style="text-align:left;"><strong>❌ 你不用管</strong></td><td style="text-align:left;">看是否“满二”免征，或由房东承担</td></tr><tr><td style="text-align:left;"><strong>个人所得税</strong></td><td style="text-align:left;">卖方（原房东）</td><td style="text-align:left;"><strong>❌ 你不用管</strong></td><td style="text-align:left;">看是否“满五唯一”免征，或由房东承担</td></tr><tr><td style="text-align:left;"><strong>维修基金</strong></td><td style="text-align:left;">买方（你）</td><td style="text-align:left;"><strong>✅ 必须交</strong>（交给房管局）</td><td style="text-align:left;"><strong>❌ 通常不用再交</strong>（随房转移）</td></tr><tr><td style="text-align:left;"><strong>中介费</strong></td><td style="text-align:left;">买方/卖方</td><td style="text-align:left;"><strong>❌ 没有中介</strong></td><td style="text-align:left;"><strong>✅ 可能需要交</strong>（如果通过中介）</td></tr></tbody></table><hr><h2 id="个人所得税和增值税的区别" tabindex="-1">个人所得税和增值税的区别 <a class="header-anchor" href="#个人所得税和增值税的区别" aria-label="Permalink to &quot;个人所得税和增值税的区别&quot;">​</a></h2><blockquote><p>说个事实，其实个人所得税和增值税都是由卖家上缴给国家的，但是呢，羊毛出在羊身上，最后都是由消费者买单，你最后买到手的东西已经包含了卖家所需要缴纳的这些钱。</p><ul><li>增值税：由企业自己以公司名义去申报缴纳。</li><li>个人所得税：通常由企业（发钱方）替个人（收钱方）代扣代缴，个人很少需要亲自跑税务局。</li></ul></blockquote><p>打个比方， 一瓶5元水的价格构成</p><p>假设这瓶水在超市的最终售价是 <strong>5元</strong>（含税），这5元钱大致分给了三个地方：</p><ol><li><strong>水的生产成本 + 企业利润</strong>（约3.5元）</li><li><strong>增值税</strong>（约0.3元）</li><li><strong>其他税费</strong>（如城建税、教育费附加等，约0.2元）</li><li><strong>终端零售商的利润</strong>（约1元）</li></ol><hr><p><strong>1. 增值税（你一定在付）</strong></p><ul><li><strong>性质</strong>：这是一种<strong>流转税</strong>，只要商品每经过一道买卖环节（厂家→批发商→超市→你），有“增值”了，就要交。</li><li><strong>在5元水里</strong>：超市卖给你5元，这5元里已经包含了它要交给国家的增值税。税率一般是13%（生活必需品可能有优惠），所以大概有 <strong>5 ÷ (1+13%) × 13% ≈ 0.58元</strong> 是增值税。</li><li><strong>你确实在买单</strong>：这0.58元就包含在你付的5元里，由超市代收代缴给国家。</li></ul><p><strong>2. 个人所得税（你不直接付，但“间接”付了）</strong></p><ul><li><strong>性质</strong>：这是对<strong>个人/企业赚取的利润</strong>征收的税。</li><li><strong>在5元水里</strong>：你买水，<strong>不需要为这笔消费行为交个税</strong>。个税是超市老板或厂家老板赚钱后，按他们企业的利润去交的。</li><li><strong>但是，企业定价时会算进去</strong>：老板会想：“我卖一瓶水，除去成本、增值税、房租、人工之后，还要留下利润。如果利润要交25%的企业所得税（类似企业的个税），那我得把价格定高一点，保证交完税后还能赚到钱。”</li><li>虽然小票上不写“个税”这一项，但它确实通过<strong>提高商品价格</strong>的方式，让你间接分担了。</li></ul><hr><div class="tip custom-block github-alert"><p class="custom-block-title">各位看官有没有发现一个问题，我身为一个消费者，买个东西，又是附加个税 又是增值税的，感觉是不是 这俩税是不是有点重复？？？</p><p></p></div><p>举个例子，比如你是一个矿泉水的源头厂家。卖货给超市</p><table tabindex="0"><thead><tr><th style="text-align:left;">项目</th><th style="text-align:left;">金额</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>超市付给你的总金额</strong></td><td style="text-align:left;"><strong>+3.00元</strong></td><td style="text-align:left;">这是超市扫码付给你的钱</td></tr><tr><td style="text-align:left;">其中：真实的水费</td><td style="text-align:left;">+2.65元</td><td style="text-align:left;">这才是你卖水真正赚流水的那部分钱</td></tr><tr><td style="text-align:left;">其中：代收的增值税</td><td style="text-align:left;">+0.35元</td><td style="text-align:left;">这钱只是在你账户里过个路，下个月要交给国家</td></tr><tr><td style="text-align:left;"><strong>你的制水成本</strong></td><td style="text-align:left;"><strong>-1.00元</strong></td><td style="text-align:left;">买原材料、电费、机器损耗</td></tr><tr><td style="text-align:left;"><strong>你的真实毛利</strong></td><td style="text-align:left;"><strong>= 1.65元</strong></td><td style="text-align:left;">这是你卖这瓶水真正落袋为安的毛利润</td></tr><tr><td style="text-align:left;"><strong>减：销售费用</strong></td><td style="text-align:left;"><strong>-0.30元</strong></td><td style="text-align:left;">付给销售员的提成、广告分摊</td></tr><tr><td style="text-align:left;"><strong>减：管理费用</strong></td><td style="text-align:left;"><strong>-0.20元</strong></td><td style="text-align:left;">厂长的工资分摊、办公费</td></tr><tr><td style="text-align:left;"><strong>减：财务费用</strong></td><td style="text-align:left;"><strong>-0.10元</strong></td><td style="text-align:left;">银行贷款的利息分摊</td></tr><tr><td style="text-align:left;"><strong>你的营业利润</strong></td><td style="text-align:left;"><strong>= 1.05元</strong></td><td style="text-align:left;">这是你主业经营赚到的钱</td></tr><tr><td style="text-align:left;"><strong>加/减：营业外收支</strong></td><td style="text-align:left;"><strong>0元</strong></td><td style="text-align:left;">比如罚款、政府补贴等，假设没有</td></tr><tr><td style="text-align:left;"><strong>你的利润总额</strong></td><td style="text-align:left;"><strong>= 1.05元</strong></td><td style="text-align:left;">这是你税前总共赚的钱</td></tr><tr><td style="text-align:left;"><strong>减：企业所得税</strong></td><td style="text-align:left;"><strong>-0.21元</strong></td><td style="text-align:left;">利润总额 × 20%（小型微利企业优惠税率）</td></tr><tr><td style="text-align:left;"><strong>你的税后净利润</strong></td><td style="text-align:left;"><strong>= 0.84元</strong></td><td style="text-align:left;">这是你企业最终净利润（可不是进你自己银行卡）</td></tr><tr><td style="text-align:left;"><strong>减：分红环节的个人所得税</strong></td><td style="text-align:left;"><strong>-0.10元</strong></td><td style="text-align:left;">你要给自己发工资，要交20%的个税（由企业代扣代缴）</td></tr><tr><td style="text-align:left;"><strong>你身为老板最后银行卡的余额</strong></td><td style="text-align:left;"><strong>0.74元</strong></td><td style="text-align:left;">你身为老板最后银行卡的余额</td></tr></tbody></table><p><strong>最后我来说下 这俩的区别</strong></p><ul><li><strong>增值税</strong>：<strong>“对事不对人”</strong>。它不看是谁在卖，也不管这个人赚没赚钱，只要这件<strong>商品</strong>（或服务）在流转过程中产生了“增值”，它就要被征收一次流转税。它是<strong>附着在商品流动链条上的“过路费”</strong>。</li><li><strong>个人所得税</strong>：<strong>“对人不对事”</strong>。它不看卖的是什么商品，只看<strong>卖东西的这个人</strong>（或企业）最终口袋里<strong>赚了多少钱</strong>。如果亏本了，哪怕商品流转了一百次，这个人也不用交个税。它是<strong>针对盈利主体口袋里的“分成”</strong>。</li></ul><hr><p><strong>用一个极端的例子验证你的理解</strong></p><p>假设你作为厂家，<strong>亏本卖水</strong>：</p><ul><li><strong>情况</strong>：你进原料花了3元（成本），但因为滞销，你只能<strong>以2元的价格</strong>卖给超市。</li><li><strong>增值税</strong>：虽然你亏了1元，但你**“卖水”这个动作依然存在**。你以2元成交，这2元里依然包含增值税（约0.23元），你必须交给国家。<strong>商品在流转，税就躲不掉。</strong></li><li><strong>个人所得税（企业所得税）</strong>：你亏了1元（2元售价 - 3元成本 = -1元），<strong>没有盈利</strong>，所以你<strong>一分钱所得税都不用交</strong>。<strong>人没赚钱，就不用分钱给国家。</strong></li></ul><p>这个例子完美印证了：<strong>增值税认“商品”，个税认“人”的盈利。</strong></p>`,78)])])}const h=l(r,[["render",g]]);export{y as __pageData,h as default};
